const keys=Object.keys(words).sort((a,b)=>b.length-a.length);
const pattern=new RegExp(keys.map(s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');
function text(s){if(typeof s!=='string')return s;if(s==='本')return '手稿';return s.replace(pattern,m=>words[m]).replace(/\bLvl?\./g,'等級 ');}
function htmlBody(html){let body=false;return html.replace(/<!--[\s\S]*?-->|<script\b[^>]*>[\s\S]*?<\/script\s*>|<style\b[^>]*>[\s\S]*?<\/style\s*>|<[^>]+>|[^<]+/gi,token=>{if(/^<body\b/i.test(token))body=true;if(/^<\/body/i.test(token))body=false;return body&&!token.startsWith('<')?text(token):token;});}
function localizeMaster(e){
 const copy=structuredClone(e),chosen=e.localizations.ja||e.localizations.en;
 if(chosen)copy.localizations['zh-tw']={...chosen,name:e.names.en,skillNames:chosen.skillNames.map(text),tables:chosen.tables.map(t=>({...t,heading:text(t.heading),headers:t.headers.map(text),rows:t.rows.map(r=>r.map(text))}))};
 copy.reference.type=text(copy.reference.type);
 for(const c of copy.reference.classes)c.name=text(c.name);
 for(const s of [...copy.reference.skills,copy.reference.talent]){s.name=text(s.name);s.valueLabels=s.valueLabels.map(text);}
 return copy;
}
