const types={'Archer':'弓兵','Cavalry':'騎兵','Infantry':'步兵',"Squads'":'全體部隊'},stats={'Attack':'攻擊力','Defense':'防禦力','Health':'生命值','Lethality':'殺傷力'};
function allianceName(n){const suffix=n.match(/ (I|II|III)$/)?.[0]||'',base=suffix?n.slice(0,-suffix.length):n;if(names[base])return names[base]+suffix;for(const[t,tw]of Object.entries(types))for(const[s,v]of Object.entries(stats))if(base===t+' '+s)return tw+v+suffix;throw Error('Missing TW alliance name: '+n);}
function allianceDescription(s){if(!s)return s;if(desc[s])return desc[s];const m=s.match(/^Enhances (Archer|Cavalry|Heavy Infantry|Infantry|all Squads') (Attack|Defense|Health|Lethality)\.$/);if(m)return '提升'+(types[m[1].replace('Heavy ','').replace('all ','')]||'全體部隊')+'的'+stats[m[2]]+'。';throw Error('Missing TW alliance description: '+s);}
function localizeAlliance(model){const copy=structuredClone(model);for(const e of copy.entities){e.names['zh-tw']=allianceName(e.names.en);e.descriptions['zh-tw']=allianceDescription(e.descriptions.en);}return copy;}
module.exports={text,htmlBody,localizeMaster,localizeAlliance};
